require_once __DIR__ . '/config/bootstrap.php';
$page=$_GET['page']??'dashboard';
if($page==='activity'){
 $pageTitle='Aktivitas Sistem';$active='activity';require __DIR__.'/partials/header.php';$logs=$pdo->query('SELECT * FROM activity_logs ORDER BY created_at DESC LIMIT 50')->fetchAll();
 ?><section class="card"><div class="card-head"><div><h2>Riwayat aktivitas</h2><span class="muted">Jejak perubahan data inventaris.</span></div></div><div class="activity"><?php foreach($logs as $log): ?><div class="activity-item"><div class="activity-dot">✓</div><div><strong><?= e($log['action']) ?></strong><div><?= e($log['description']) ?></div><span class="muted"><?= e($log['created_at']) ?></span></div></div><?php endforeach; ?><?php if(!$logs): ?><div class="empty">Belum ada aktivitas.</div><?php endif; ?></div></section><?php require __DIR__.'/partials/footer.php';exit;
}
if($page==='products'){
 $pageTitle='Daftar Produk';$active='products';require __DIR__.'/partials/header.php';$q=trim($_GET['q']??'');$category=(int)($_GET['category']??0);$supplier=(int)($_GET['supplier']??0);$status=$_GET['status']??'';$perPage=5;$current=max(1,(int)($_GET['p']??1));$where=[];$params=[];
 if($q!==''){$where[]='(p.name LIKE :q OR c.name LIKE :q OR s.name LIKE :q)';$params['q']='%'.$q.'%';} if($category){$where[]='p.category_id=:category';$params['category']=$category;} if($supplier){$where[]='p.supplier_id=:supplier';$params['supplier']=$supplier;} if($status==='critical')$where[]='p.stock<=5'; if($status==='low')$where[]='p.stock BETWEEN 6 AND 10'; if($status==='safe')$where[]='p.stock>10';
 $whereSql=$where?'WHERE '.implode(' AND ',$where):'';$countStmt=$pdo->prepare("SELECT COUNT(*) FROM products p JOIN categories c ON c.id=p.category_id JOIN suppliers s ON s.id=p.supplier_id $whereSql");$countStmt->execute($params);$total=(int)$countStmt->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$current=min($current,$pages);$offset=($current-1)*$perPage;
 $sql="SELECT p.*,c.name category_name,s.name supplier_name FROM products p JOIN categories c ON c.id=p.category_id JOIN suppliers s ON s.id=p.supplier_id $whereSql ORDER BY p.id DESC LIMIT :limit OFFSET :offset";$stmt=$pdo->prepare($sql);foreach($params as $key=>$value)$stmt->bindValue(':'.$key,$value);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$products=$stmt->fetchAll();$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$suppliers=$pdo->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();
 ?><section class="card table-card"><div class="table-tools"><div><strong>Semua Produk</strong><div class="muted"><?= $total ?> produk ditemukan</div></div><form class="filters" method="get"><input type="hidden" name="page" value="products"><input class="input" name="q" value="<?= e($q) ?>" placeholder="Cari produk..."><select class="select" name="category"><option value="0">Semua kategori</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $category===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><select class="select" name="supplier"><option value="0">Semua supplier</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>" <?= $supplier===$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select><select class="select" name="status"><option value="">Semua stok</option><option value="safe" <?= $status==='safe'?'selected':'' ?>>Aman</option><option value="low" <?= $status==='low'?'selected':'' ?>>Menipis</option><option value="critical" <?= $status==='critical'?'selected':'' ?>>Kritis</option></select><button class="btn btn-light" type="submit">Filter</button></form></div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Produk</th><th>Kategori</th><th>Supplier</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $i=>$product):$stock=(int)$product['stock'];$cls=$stock<=5?'critical':($stock<=10?'low':'safe');$label=$cls==='critical'?'Kritis':($cls==='low'?'Menipis':'Aman'); ?><tr><td><?= $offset+$i+1 ?></td><td><span class="product-name"><?= e($product['name']) ?></span><span class="sub">ID #<?= $product['id'] ?></span></td><td><?= e($product['category_name']) ?></td><td><?= e($product['supplier_name']) ?></td><td><?= rupiah($product['price']) ?></td><td><span class="badge <?= $cls ?>"><?= $stock ?> • <?= $label ?></span></td><td><div class="actions"><a class="action edit" href="edit.php?id=<?= $product['id'] ?>">Edit</a><form method="post" action="actions/delete.php" onsubmit="return confirmDelete('<?= e($product['name']) ?>')" style="display:inline"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= $product['id'] ?>"><button class="action delete" type="submit">Hapus</button></form></div></td></tr><?php endforeach; ?><?php if(!$products): ?><tr><td colspan="7"><div class="empty">Tidak ada produk yang sesuai dengan filter.</div></td></tr><?php endif; ?></tbody></table></div><?php if($pages>1): ?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):$paramsUrl=$_GET;$paramsUrl['p']=$i; ?><a class="page <?= $i===$current?'active':'' ?>" href="?<?= http_build_query($paramsUrl) ?>"><?= $i ?></a><?php endfor; ?></div><?php endif; ?></section><?php require __DIR__.'/partials/footer.php';exit;
}
$pageTitle='Dashboard';$active='dashboard';require __DIR__.'/partials/header.php';$totalProducts=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$totalStock=(int)$pdo->query('SELECT COALESCE(SUM(stock),0) FROM products')->fetchColumn();$totalValue=(float)$pdo->query('SELECT COALESCE(SUM(price*stock),0) FROM products')->fetchColumn();$lowStock=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock<=10')->fetchColumn();$catRows=$pdo->query('SELECT c.name,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name ORDER BY total DESC,c.name')->fetchAll();$recent=$pdo->query('SELECT p.name,c.name category_name,p.stock,p.price FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 5')->fetchAll();$maxCat=max(1,...array_map(fn($x)=>(int)$x['total'],$catRows));
?><section class="stats"><div class="stat"><div class="icon">▤</div><div class="label">TOTAL PRODUK</div><div class="value"><?= $totalProducts ?></div><div class="accent"></div></div><div class="stat"><div class="icon">▥</div><div class="label">TOTAL STOK</div><div class="value"><?= number_format($totalStock) ?></div><div class="accent"></div></div><div class="stat"><div class="icon">Rp</div><div class="label">NILAI INVENTARIS</div><div class="value" style="font-size:20px"><?= rupiah($totalValue) ?></div><div class="accent"></div></div><div class="stat"><div class="icon">!</div><div class="label">STOK MENIPIS</div><div class="value"><?= $lowStock ?></div><div class="accent"></div></div></section><section class="grid-2"><div class="card"><div class="card-head"><div><h2>Produk per Kategori</h2><span class="muted">Distribusi data inventaris</span></div><a href="index.php?page=products" class="btn btn-light">Lihat produk</a></div><div class="bars"><?php foreach($catRows as $row): ?><div class="bar-row"><span><?= e($row['name']) ?></span><div class="bar-track"><div class="bar-fill" style="width:<?= ((int)$row['total']/$maxCat)*100 ?>%"></div></div><strong><?= $row['total'] ?></strong></div><?php endforeach; ?></div></div><div class="card"><div class="card-head"><div><h2>Status Stok</h2><span class="muted">Perhatian pada stok ≤ 10</span></div></div><div class="bars"><div class="bar-row"><span>Aman</span><div class="bar-track"><div class="bar-fill" style="width:<?= $totalProducts?min(100,(count(array_filter($recent,fn($x)=>$x['stock']>10))/$totalProducts)*100):0 ?>%"></div></div><strong><?= max(0,$totalProducts-$lowStock) ?></strong></div><div class="bar-row"><span>Menipis</span><div class="bar-track"><div class="bar-fill" style="width:<?= $totalProducts?($lowStock/$totalProducts)*100:0 ?>%"></div></div><strong><?= $lowStock ?></strong></div></div></div></section><section class="card table-card"><div class="table-tools"><div><strong>Produk Terbaru</strong><div class="muted">5 data terakhir</div></div><a class="btn btn-primary" href="create.php">＋ Produk baru</a></div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td class="product-name"><?= e($r['name']) ?></td><td><?= e($r['category_name']) ?></td><td><?= rupiah($r['price']) ?></td><td><?= $r['stock'] ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
